import{_ as e,o,c as r,a3 as a}from"./chunks/framework.CWCEHGF4.js";const d="/MeshPaintingDoc/painting-controller/01-add-component.png",n="/MeshPaintingDoc/painting-controller/02-controls-input.png",i="/MeshPaintingDoc/painting-controller/06-target-paint.png",s="/MeshPaintingDoc/painting-controller/08-brush-settings.png",c="/MeshPaintingDoc/painting-controller/03-widget-cursor.png",l="/MeshPaintingDoc/painting-controller/10-runtime-color-picker.png",h="/MeshPaintingDoc/painting-controller/04-brush-preview-settings.png",p="/MeshPaintingDoc/painting-controller/05-brush-preview-runtime.png",u="/MeshPaintingDoc/painting-controller/07-camera-settings.png",m="/MeshPaintingDoc/painting-controller/09-events.png",k=JSON.parse('{"title":"PaintingModeControllerComponent","description":"","frontmatter":{},"headers":[],"relativePath":"systems/painting-controller.md","filePath":"systems/painting-controller.md","lastUpdated":1786045981000}'),g={name:"systems/painting-controller.md"};function b(v,t,w,y,f,P){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="paintingmodecontrollercomponent" tabindex="-1">PaintingModeControllerComponent <a class="header-anchor" href="#paintingmodecontrollercomponent" aria-label="Permalink to &quot;PaintingModeControllerComponent&quot;">​</a></h1><p><code>PaintingModeControllerComponent</code> is the player-side controller for runtime painting.</p><p>It does not make a mesh paintable by itself. Paintable meshes still need a <code>RuntimeMeshPaintTargetComponent</code>. The controller is responsible for entering paint mode, reading player input, showing the color picker, drawing the brush preview, resolving the target under the cursor, and submitting paint commands.</p><p><img src="'+d+'" alt="PaintingModeControllerComponent added to a character"></p><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>The controller handles the player-side part of the painting workflow:</p><ul><li>Enters and exits painting mode.</li><li>Adds the paint input mapping contexts.</li><li>Traces from the mouse position into the world.</li><li>Finds the correct <code>RuntimeMeshPaintTargetComponent</code>.</li><li>Applies the current brush settings.</li><li>Shows the runtime color picker widget.</li><li>Displays the brush cursor and GPU brush area preview.</li><li>Controls paint-mode orbit, pan, zoom, and movement behavior.</li><li>Sends multiplayer paint commands when the target has replication enabled.</li></ul><h2 id="required-setup" tabindex="-1">Required Setup <a class="header-anchor" href="#required-setup" aria-label="Permalink to &quot;Required Setup&quot;">​</a></h2><p>Add <code>PaintingModeControllerComponent</code> to the locally controlled player actor that should paint.</p><p>For a normal third-person character, add it to the character blueprint. For a drone or custom pawn, add it to the pawn that owns the camera input. A <code>PlayerController</code> owner is also supported for simple setups.</p><p><code>CharacterLock</code> mode expects the owner to be a character with:</p><ul><li><code>CharacterMovement</code></li><li><code>Camera</code></li><li><code>SpringArm</code></li></ul><p>Use <code>Simple</code> mode when the owner is not a standard character or when you do not want the component to lock character movement.</p><p>For the default First Person template, start with <code>Simple</code> mode. <code>CharacterLock</code> expects a SpringArm-based character camera setup, and <code>EnterPaintingMode</code> may return <code>false</code> if that setup is missing.</p><h2 id="control-mode-and-input" tabindex="-1">Control Mode and Input <a class="header-anchor" href="#control-mode-and-input" aria-label="Permalink to &quot;Control Mode and Input&quot;">​</a></h2><p>The <code>Controls</code> and <code>Input</code> sections define how the component receives paint input.</p><p><img src="'+n+'" alt="Control mode and input assets"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Control Mode</code></td><td>Selects how much player/camera behavior the component controls.</td></tr><tr><td><code>Painting Input Mapping Context</code></td><td>Mapping context added while paint mode is active.</td></tr><tr><td><code>Painting Toggle Input Mapping Context</code></td><td>Mapping context used for toggling paint mode.</td></tr><tr><td><code>Painting Input Priority</code></td><td>Enhanced Input priority used when mapping contexts are added.</td></tr><tr><td><code>Load Default Input Assets</code></td><td>Loads the plugin default input actions and mapping contexts when fields are empty.</td></tr></tbody></table><p>Control modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>Character Lock</code></td><td>Locks normal character look behavior, shows the mouse cursor, applies paint-mode movement/camera behavior, then restores the previous state when paint mode exits.</td></tr><tr><td><code>Simple</code></td><td>Uses painting input without requiring a character movement setup. This is the safer mode for drone pawns, custom pawns, tools, and non-character controllers.</td></tr><tr><td><code>None</code></td><td>Disables the component&#39;s paint-mode input handling. Use this when you want to drive the component only from your own Blueprint or C++ code.</td></tr></tbody></table><p>Default input assets:</p><table tabindex="0"><thead><tr><th>Asset</th><th>Used For</th></tr></thead><tbody><tr><td><code>IA_Paint</code></td><td>Starts, continues, and releases a paint stroke.</td></tr><tr><td><code>IA_PickColorAction</code></td><td>Samples the color under the cursor.</td></tr><tr><td><code>IA_OrbitCamera</code></td><td>Starts camera orbit while paint mode is active.</td></tr><tr><td><code>IA_PanCamera</code></td><td>Starts camera pan. The component only accepts pan while Shift is held.</td></tr><tr><td><code>IA_CameraZoom</code></td><td>Zooms the spring arm in <code>CharacterLock</code> mode.</td></tr><tr><td><code>IA_AdjustBrushSize</code></td><td>Adjusts brush size while the action is held and mouse delta is received.</td></tr><tr><td><code>IA_AdjustBrushSizeWheel</code></td><td>Adjusts brush size from mouse wheel while Control is held.</td></tr><tr><td><code>IA_MouseDelta</code></td><td>Feeds orbit, pan, and drag-based brush size changes.</td></tr><tr><td><code>IA_PaintingMove</code></td><td>Moves the locked character in <code>CharacterLock</code> mode.</td></tr><tr><td><code>IA_TogglePaintingMode</code></td><td>Toggles paint mode through the toggle mapping context.</td></tr></tbody></table><p>The exact keys are controlled by the input mapping assets. Edit <code>IMC_PaintingMode</code> or <code>IMC_PaintingModeToggle</code> if your project needs different bindings.</p><h2 id="paint-target-and-trace" tabindex="-1">Paint Target and Trace <a class="header-anchor" href="#paint-target-and-trace" aria-label="Permalink to &quot;Paint Target and Trace&quot;">​</a></h2><p>The <code>Paint Target</code> section controls which paint target components this player is allowed to use. The <code>Paint</code> section controls trace and brush material setup.</p><p><img src="'+i+'" alt="Paint target and trace settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Auto Register</code></td><td>If enabled, the controller can automatically use a single <code>RuntimeMeshPaintTargetComponent</code> found on its owner actor.</td></tr><tr><td><code>Paint Target Components</code></td><td>Optional allow list. When this array has entries, the controller can only paint those target components.</td></tr><tr><td><code>Paint Brush Material</code></td><td>Brush material used when submitting paint to the target. The default plugin brush material is usually enough.</td></tr><tr><td><code>Paint Trace Channel</code></td><td>Collision channel used for finding the surface under the cursor. The target mesh must block this channel.</td></tr><tr><td><code>Paint Trace Complex</code></td><td>Enables complex trace data for more accurate hit information.</td></tr></tbody></table><p>Leave <code>Paint Target Components</code> empty if the player should be able to paint any valid target hit under the cursor. Fill it only when the player must be restricted to specific paint targets.</p><h2 id="brush-settings" tabindex="-1">Brush Settings <a class="header-anchor" href="#brush-settings" aria-label="Permalink to &quot;Brush Settings&quot;">​</a></h2><p>Brush settings are stored on the controller and sent to the target when paint is applied.</p><p><img src="'+s+'" alt="Brush settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Brush Size</code></td><td>Current brush size used for paint and preview.</td></tr><tr><td><code>Brush Color</code></td><td>Current paint color.</td></tr><tr><td><code>Min Brush Size</code></td><td>Lower clamp used by <code>SetBrushSize</code> and brush-size input.</td></tr><tr><td><code>Max Brush Size</code></td><td>Upper clamp used by <code>SetBrushSize</code> and brush-size input.</td></tr><tr><td><code>Brush Size Sensitivity</code></td><td>Drag-based brush size change speed.</td></tr><tr><td><code>Brush Size Wheel Sensitivity</code></td><td>Mouse wheel brush size change speed.</td></tr><tr><td><code>Brush Metallic</code></td><td>Metallic value written when material settings painting is enabled on the target.</td></tr><tr><td><code>Brush Roughness</code></td><td>Roughness value written when material settings painting is enabled on the target.</td></tr><tr><td><code>Brush Erase</code></td><td>Enables erase mode for the current brush settings.</td></tr></tbody></table><p>Use <code>SetBrushSize</code> when changing brush size from UI. It clamps the value and fires <code>OnBrushSizeChanged</code>, so sliders and labels can stay synchronized.</p><h2 id="color-picker-and-cursor" tabindex="-1">Color Picker and Cursor <a class="header-anchor" href="#color-picker-and-cursor" aria-label="Permalink to &quot;Color Picker and Cursor&quot;">​</a></h2><p>The widget section controls the automatic runtime color picker. The cursor section controls the custom brush cursor shown outside the UI.</p><p><img src="'+c+'" alt="Widget and cursor settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Auto Create Color Picker Widget</code></td><td>Creates the color picker automatically when paint mode starts.</td></tr><tr><td><code>Color Picker Widget Class</code></td><td>Widget class used for the runtime color picker. The default is <code>WBP_RuntimeColorPicker</code>.</td></tr><tr><td><code>Color Picker Widget ZOrder</code></td><td>Viewport Z order for the color picker.</td></tr><tr><td><code>Use Brush Cursor Outside UI</code></td><td>Replaces the mouse cursor with the brush cursor when the cursor is not over the painting UI.</td></tr><tr><td><code>Brush Cursor Texture</code></td><td>Texture used for the custom cursor.</td></tr><tr><td><code>Brush Cursor Hot Spot</code></td><td>Normalized cursor hotspot.</td></tr></tbody></table><p>When color picking is active or the cursor is over the color picker panel, painting and brush preview are blocked so UI interaction does not accidentally paint the mesh.</p><h3 id="custom-brush-cursor-texture" tabindex="-1">Custom Brush Cursor Texture <a class="header-anchor" href="#custom-brush-cursor-texture" aria-label="Permalink to &quot;Custom Brush Cursor Texture&quot;">​</a></h3><p>You can replace <code>Brush Cursor Texture</code> with your own <code>Texture2D</code>, but the texture must be readable by the runtime cursor builder.</p><p>Requirements for a custom cursor texture:</p><ul><li>Use a normal <code>Texture2D</code> asset.</li><li>Enable <code>CPU Copy</code> on the texture asset so the cursor pixels can be read in packaged builds.</li><li>Keep the background transparent.</li><li>Keep the texture small and readable as a cursor, usually <code>64x64</code> or <code>128x128</code>.</li><li>Set <code>Brush Cursor Hot Spot</code> to the point that should touch the painted surface.</li></ul><p>The cursor color is generated from the current <code>Brush Color</code>. The system does not use a separate mask texture. Instead, it treats visible, saturated, colored pixels in the cursor texture as the replaceable accent area.</p><p>For best results:</p><ul><li>Make only the brush tip or paint area strongly colored.</li><li>Keep the handle and outline grayscale, white, black, or low saturation if they should not change color.</li><li>Do not make the tintable tip too dark, because the source brightness is preserved when the brush color is applied.</li><li>Use alpha for clean cursor edges; nearly transparent pixels are ignored by the tint step.</li></ul><p>The default <code>T_Brush</code> texture is already prepared this way: the painted tip is the dynamic color area, while the rest of the cursor stays stable.</p><p><img src="'+l+'" alt="Runtime color picker"></p><h2 id="brush-area-preview" tabindex="-1">Brush Area Preview <a class="header-anchor" href="#brush-area-preview" aria-label="Permalink to &quot;Brush Area Preview&quot;">​</a></h2><p>The brush area preview is now generated through the same GPU projection path used by painting.</p><p>The controller resolves the hit under the cursor, asks the target component to update its <code>BrushPreviewMaskRenderTarget</code>, and the <code>Mesh Painting</code> material function displays that mask on the mesh. This means the preview is not a separate world-space brush mesh anymore. It is a render-target mask on the painted material, so it follows the paintable UV/surface result much more closely.</p><p><img src="'+h+'" alt="Brush area preview settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Enable Brush Area Preview</code></td><td>Enables or disables the surface ring preview.</td></tr><tr><td><code>Brush Area Preview Line Thickness</code></td><td>Base thickness of the preview ring.</td></tr><tr><td><code>Brush Area Preview Thickness Brush Size Multiplier</code></td><td>Adds extra line thickness as brush size increases.</td></tr><tr><td><code>Brush Area Preview Color</code></td><td>Tint multiplied with the current brush color. White keeps the ring in the active paint color.</td></tr><tr><td><code>Brush Area Preview Emissive Intensity</code></td><td>Brightness multiplier for the preview mask. This makes the ring readable without using the old brush mesh preview.</td></tr></tbody></table><p><img src="'+p+'" alt="Brush area preview in game"></p><p>The material must connect the <code>Brush Emissive</code> output from the <code>Mesh Painting</code> material function to <code>Emissive Color</code>. If that output is not connected, painting can still work, but the brush area preview will not be visible on the mesh.</p><p>The preview follows the same paint target filtering and trace channel as painting. It is hidden when the cursor is over the color picker UI or when eyedropper mode is active. Short transient trace misses are held briefly to avoid visible flicker.</p><p>Advanced Blueprint-only tuning:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Brush Area Preview Opacity</code></td><td>Alpha multiplier for the preview mask.</td></tr><tr><td><code>Brush Area Preview Brush Size Scale</code></td><td>Multiplies preview radius without changing the actual paint brush size. Keep this at <code>1.0</code> unless you intentionally want preview-only scaling.</td></tr></tbody></table><h2 id="camera-and-movement" tabindex="-1">Camera and Movement <a class="header-anchor" href="#camera-and-movement" aria-label="Permalink to &quot;Camera and Movement&quot;">​</a></h2><p>Camera settings only affect the owner while paint mode is active. When paint mode exits, zoom and pan changes are restored smoothly.</p><p><img src="'+u+'" alt="Camera, orbit, and movement settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Painting Movement Speed</code></td><td>Movement speed used in <code>CharacterLock</code> mode.</td></tr><tr><td><code>Orbit Yaw Sensitivity</code></td><td>Horizontal orbit sensitivity.</td></tr><tr><td><code>Orbit Pitch Sensitivity</code></td><td>Vertical orbit sensitivity.</td></tr><tr><td><code>Minimum Orbit Pitch</code></td><td>Lower pitch clamp.</td></tr><tr><td><code>Maximum Orbit Pitch</code></td><td>Upper pitch clamp.</td></tr><tr><td><code>Camera Zoom Sensitivity</code></td><td>Spring arm zoom speed.</td></tr><tr><td><code>Minimum Camera Zoom Distance</code></td><td>Closest allowed zoom distance.</td></tr><tr><td><code>Maximum Camera Zoom Distance</code></td><td>Farthest configured zoom distance. The controller does not zoom farther than the pre-paint default position.</td></tr><tr><td><code>Camera Pan Sensitivity</code></td><td>Pan movement speed.</td></tr><tr><td><code>Camera Pan Max Offset</code></td><td>Maximum pan offset from the saved default position. <code>0</code> removes this clamp.</td></tr><tr><td><code>Camera Restore Smoothing Speed</code></td><td>Speed used when restoring zoom and pan after paint mode exits.</td></tr></tbody></table><p>Orbit and pan stop active painting before moving the camera. Brush size adjustment also stops painting so input states do not overlap.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>The component exposes Blueprint events for paint mode and input state changes.</p><p><img src="'+m+'" alt="PaintingModeControllerComponent events"></p><table tabindex="0"><thead><tr><th>Event</th><th>When It Fires</th><th>Typical Use</th></tr></thead><tbody><tr><td><code>OnPaintingModeEntered</code></td><td>After paint mode successfully starts.</td><td>Open custom UI, update HUD state, or enable paint-only gameplay logic.</td></tr><tr><td><code>OnPaintingModeExited</code></td><td>After paint mode exits and previous input/camera state is restored.</td><td>Close custom UI or return the HUD to normal gameplay state.</td></tr><tr><td><code>OnPaintPressed</code></td><td>When the paint input starts a new stroke.</td><td>Start stroke feedback.</td></tr><tr><td><code>OnPaintTriggered</code></td><td>While the paint input continues. This can fire many times during one stroke.</td><td>Lightweight per-stroke feedback only. Avoid heavy Blueprint work here.</td></tr><tr><td><code>OnPaintReleased</code></td><td>When the current stroke ends.</td><td>End stroke feedback or commit UI state.</td></tr><tr><td><code>OnBrushSizeChanged</code></td><td>After <code>SetBrushSize</code> changes the clamped brush size.</td><td>Update brush size sliders, text, or preview UI.</td></tr><tr><td><code>OnOrbitStarted</code></td><td>When camera orbit starts.</td><td>Hide conflicting UI or show camera-control feedback.</td></tr><tr><td><code>OnOrbitStopped</code></td><td>When camera orbit stops.</td><td>Restore UI hidden during orbit.</td></tr><tr><td><code>OnComponentActivated</code></td><td>Standard Unreal component event.</td><td>Normal component activation logic only.</td></tr><tr><td><code>OnComponentDeactivated</code></td><td>Standard Unreal component event.</td><td>Normal component deactivation logic only.</td></tr></tbody></table><h2 id="useful-blueprint-functions" tabindex="-1">Useful Blueprint Functions <a class="header-anchor" href="#useful-blueprint-functions" aria-label="Permalink to &quot;Useful Blueprint Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Use</th></tr></thead><tbody><tr><td><code>EnterPaintingMode</code></td><td>Starts paint mode, adds the painting mapping context, creates the widget, and shows the cursor.</td></tr><tr><td><code>ExitPaintingMode</code></td><td>Leaves paint mode, removes the mapping context/widget, stops input states, and restores camera/input state.</td></tr><tr><td><code>SetBrushSize</code></td><td>Changes brush size with min/max clamping and broadcasts <code>OnBrushSizeChanged</code>.</td></tr><tr><td><code>SetBrushAreaPreviewEnabled</code></td><td>Enables or disables the surface preview ring.</td></tr><tr><td><code>SetPaintTargetComponent</code></td><td>Restricts painting to one target component.</td></tr><tr><td><code>SetPaintTargetComponents</code></td><td>Restricts painting to a list of target components.</td></tr><tr><td><code>AddPaintTargetComponent</code></td><td>Adds one target component to the allow list.</td></tr><tr><td><code>ClearPaintTargetComponents</code></td><td>Clears the allow list so hit-based target discovery can be used again.</td></tr><tr><td><code>GetBrushMaterialSettings</code></td><td>Returns the current color, size, metallic, roughness, and erase state as brush settings.</td></tr><tr><td><code>ApplyBrushMaterialSettings</code></td><td>Applies external brush settings to the controller.</td></tr><tr><td><code>SamplePaintedSurfaceColor</code></td><td>Samples color through the resolved paint target.</td></tr><tr><td><code>ApplyPaint</code></td><td>Applies paint under the current cursor position. Normally called by input.</td></tr></tbody></table><h2 id="multiplayer-behavior" tabindex="-1">Multiplayer Behavior <a class="header-anchor" href="#multiplayer-behavior" aria-label="Permalink to &quot;Multiplayer Behavior&quot;">​</a></h2><p>The controller is the multiplayer submission point for player input.</p><p>When the target has <code>Replicate Runtime Paint</code> enabled, the controller applies local prediction first, then submits a compact paint command batch to the server.</p><p>For skeletal meshes, the command also carries screen projection data so other clients can reproduce the same GPU projected brush without using the old CPU skeletal UV fallback path. The target component validates and stores the authoritative paint history. Late join and replay details are covered in <a href="/MeshPaintingDoc/systems/multiplayer">Multiplayer</a>.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li><code>Control Mode</code> is set to <code>None</code>, so no paint input is added.</li><li><code>CharacterLock</code> is used on an actor that is not a character with camera, spring arm, and movement components.</li><li><code>Paint Target Components</code> contains the wrong target, so valid meshes under the cursor are ignored.</li><li>The target mesh does not block the selected <code>Paint Trace Channel</code>.</li><li><code>Load Default Input Assets</code> is disabled but custom input actions or mapping contexts were not assigned.</li><li>Heavy Blueprint logic is bound to <code>OnPaintTriggered</code>, causing hitches during continuous strokes.</li><li>The cursor is over the color picker UI, so painting and preview are intentionally blocked.</li><li>The material does not connect <code>Brush Emissive</code> to <code>Emissive Color</code>, so the GPU brush area preview mask is generated but not visible.</li></ul>',74)])])}const x=e(g,[["render",b]]);export{k as __pageData,x as default};
